package com.bank.sre;

// A recurring operational task and its toil characteristics.
public class ToilTask {
    private final String name;
    private final boolean manual;
    private final boolean repetitive;
    private final boolean automatable;
    private final boolean noEnduringValue;
    private final boolean scalesWithService;
    private final int minutesPerOccurrence;
    private final int occurrencesPerMonth;

    public ToilTask(String name, boolean manual, boolean repetitive, boolean automatable,
                    boolean noEnduringValue, boolean scalesWithService,
                    int minutesPerOccurrence, int occurrencesPerMonth) {
        this.name = name;
        this.manual = manual;
        this.repetitive = repetitive;
        this.automatable = automatable;
        this.noEnduringValue = noEnduringValue;
        this.scalesWithService = scalesWithService;
        this.minutesPerOccurrence = minutesPerOccurrence;
        this.occurrencesPerMonth = occurrencesPerMonth;
    }

    public String getName() { return name; }
    public int monthlyMinutes() { return minutesPerOccurrence * occurrencesPerMonth; }

    // How many of the five toil traits this task exhibits (0..5).
    public int toilScore() {
        int s = 0;
        if (manual) s++;
        if (repetitive) s++;
        if (automatable) s++;
        if (noEnduringValue) s++;
        if (scalesWithService) s++;
        return s;
    }
}
