package com.bank.sre;

import java.util.logging.Logger;

// Scores a task as toil and measures the time it consumes.
public class ToilTracker {
    private static final Logger log = Logger.getLogger(ToilTracker.class.getName());

    private static final int WORK_MINUTES_PER_MONTH = 160 * 60;   // ~1 engineer-month

    public boolean assess(ToilTask task) {
        int score = task.toilScore();
        int minutes = task.monthlyMinutes();
        double percentOfEngineer = 100.0 * minutes / WORK_MINUTES_PER_MONTH;

        log.info(() -> String.format("TASK '%s': toil score %d/5, %d min/month (%.1f%% of an engineer)",
            task.getName(), score, minutes, percentOfEngineer));

        boolean isToil = score >= 4;   // matches most toil characteristics
        if (isToil && percentOfEngineer > 10) {
            log.warning(() -> "HIGH TOIL: '" + task.getName()
                    + "' is clearly toil and consuming significant time — prioritise reduction");
        } else if (isToil) {
            log.info(() -> "TOIL: '" + task.getName() + "' is toil but small — automate when convenient");
        } else {
            log.info(() -> "NOT TOIL: '" + task.getName() + "' needs human judgement — keep");
        }
        return isToil;
    }
}
