package com.bank.sre;

import java.util.logging.Logger;

// Replaces a manual toil task. Two levels: automate the fix, then fix root cause.
public class Automation {
    private static final Logger log = Logger.getLogger(Automation.class.getName());

    // Level 1: automate the cleanup — manual minutes drop to near zero.
    public int automateCleanup(ToilTask task) {
        log.info(() -> "AUTOMATE: scheduled job now reprocesses stuck transfers for "
                + "'" + task.getName() + "' — engineer minutes -> 0");
        return 0;   // engineer no longer spends time
    }

    // Level 2: fix the root cause so the task stops being generated at all.
    public void fixRootCause() {
        log.info("ROOT CAUSE FIXED: added idempotent retry + timeout so transfers no longer "
               + "get stuck — the toil is ELIMINATED, not just automated");
    }
}
