package com.bank.sre;

import java.util.logging.*;

// Runnable demo: measure the nightly reprocessing toil, automate it, then fix the root cause.
public class ToilDemo {
    private static final Logger log = Logger.getLogger(ToilDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — reducing nightly stuck-transfer toil");

        // The nightly manual reprocessing: 45 min each night, every night, grows with volume.
        ToilTask nightlyReprocess = new ToilTask(
            "manual nightly stuck-transfer reprocessing",
            true, true, true, true, true,   // all 5 toil traits
            45, 30);                         // 45 min x 30 nights
        ToilTracker tracker = new ToilTracker();

        boolean isToil = tracker.assess(nightlyReprocess);

        if (isToil) {
            Automation automation = new Automation();
            // Level 1: automate the reprocessing.
            int after = automation.automateCleanup(nightlyReprocess);
            log.info("Before: " + nightlyReprocess.monthlyMinutes()
                   + " engineer-min/month. After automation: " + after + " min/month.");
            // Level 2: fix the root cause so stuck transfers stop happening.
            automation.fixRootCause();
        }

        // A counter-example: a task that genuinely needs judgement is NOT toil.
        ToilTask capacityReview = new ToilTask(
            "quarterly capacity planning review",
            true, false, false, false, false, 240, 1);
        tracker.assess(capacityReview);
    }
}
